// Create CGAL kernel and triangulation types
typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef CGAL::Triangulation_vertex_base_2<K> Vb;
typedef CGAL::Triangulation_face_base_2<K> Fb;
typedef CGAL::Triangulation_data_structure_2<Vb, Fb> TDS;
typedef CGAL::Delaunay_triangulation_2<K, TDS> DT;
typedef DT::Point CGALPoint;

DT dt;
for (const auto& p : points) {
    dt.insert(CGALPoint(p.x(), p.y()));
}

// Mark faces based on alpha criterion
std::vector<bool> is_alpha_face(dt.number_of_faces(), false);
int face_index = 0;
for (DT::Finite_faces_iterator fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit, ++face_index) {
    CGALPoint p0 = fit->vertex(0)->point();
    CGALPoint p1 = fit->vertex(1)->point();
    CGALPoint p2 = fit->vertex(2)->point();

    // Compute circumradius of the triangle
    CGAL::Circle_2<K> circ = dt.circumcircle(fit);
    double r = std::sqrt(circ.squared_radius());

    // Keep face if circumradius <= alpha
    if (r <= alpha) {
        is_alpha_face[face_index] = true;
    }
}

// Build alpha shape as a set of triangles
std::vector<std::array<Point2d, 3>> alpha_triangles;
face_index = 0;
for (DT::Finite_faces_iterator fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit, ++face_index) {
    if (is_alpha_face[face_index]) {
        CGALPoint p0 = fit->vertex(0)->point();
        CGALPoint p1 = fit->vertex(1)->point();
        CGALPoint p2 = fit->vertex(2)->point();
        std::array<Point2d, 3> tri;
        tri[0] = Point2d(p0.x(), p0.y());
        tri[1] = Point2d(p1.x(), p1.y());
        tri[2] = Point2d(p2.x(), p2.y());
        alpha_triangles.push_back(tri);
    }
}

// Count connected components using union-find or DFS on alpha triangles
if (alpha_triangles.empty()) return 0;

std::vector<bool> visited(alpha_triangles.size(), false);
int components = 0;

// Helper: check if two triangles share an edge
auto shareEdge = [](const std::array<Point2d, 3>& t1, const std::array<Point2d, 3>& t2) {
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            if (t1[i] == t2[j] && t1[(i+1)%3] == t2[(j+1)%3]) return true;
            if (t1[i] == t2[j] && t1[(i+1)%3] == t2[(j+2)%3]) return true;
        }
    }
    return false;
};

// DFS to count connected components
for (size_t i = 0; i < alpha_triangles.size(); ++i) {
    if (!visited[i]) {
        components++;
        std::vector<size_t> stack;
        stack.push_back(i);
        visited[i] = true;
        while (!stack.empty()) {
            size_t curr = stack.back();
            stack.pop_back();
            for (size_t j = 0; j < alpha_triangles.size(); ++j) {
                if (!visited[j] && shareEdge(alpha_triangles[curr], alpha_triangles[j])) {
                    visited[j] = true;
                    stack.push_back(j);
                }
            }
        }
    }
}

return components;

